108	@Service
109	public class PricingService {
110	    private final ProductRepository productRepository;
111	    private final TransLogClient transLogClient;
112	
113	    public PricingService(ProductRepository productRepository, TransLogClient transLogClient) {
114	        this.productRepository = productRepository;
115	        this.transLogClient = transLogClient;
116	    }
117	
118	    public OrderSummary calculateSummary(OrderRequestDTO request) {
119	        BigDecimal productsSubtotal = calculateProductsSubtotal(request.getItems());
120	        BigDecimal couponDiscount = calculateCouponDiscount(request.getCoupon(), productsSubtotal, request.getShippingMethod(), request);
121	
122	        ShippingCostInfo shippingInfo = calculateShippingCost(request);
123	        BigDecimal shippingCost = shippingInfo.cost;
124	        Integer deliveryDays = shippingInfo.days;
125	
126	        BigDecimal insurance = calculateInsurance(productsSubtotal, request.getRegion());
127	
128	        BigDecimal subtotalBeforePayment = PricingUtil.add(
129	            PricingUtil.subtract(productsSubtotal, couponDiscount),
130	            PricingUtil.add(shippingCost, insurance)
131	        );
132	
133	        validatePaymentMethodConstraints(request, subtotalBeforePayment);
134	
135	        PaymentAdjustmentInfo adjustmentInfo = calculatePaymentAdjustment(
136	            request.getPaymentMethod(),
137	            subtotalBeforePayment,
138	            request.getInstallments(),
139	            request.getCoupon() != null && !request.getCoupon().isEmpty()
140	        );
141	
142	        BigDecimal finalTotal = adjustmentInfo.finalTotal;
143	        Integer installments = adjustmentInfo.installments;
144	        BigDecimal installmentAmount = adjustmentInfo.installmentAmount;
145	
146	        BigDecimal nextPurchaseCredit = calculateNextPurchaseCredit(request.getClubTier(), productsSubtotal);
147	
148	        Boolean gift = shouldGiveGift(request.getClubTier(), productsSubtotal);
149	
150	        return new OrderSummary(
151	            productsSubtotal,
152	            couponDiscount,
153	            shippingCost,
154	            deliveryDays,
155	            insurance,
156	            adjustmentInfo.adjustment,
157	            finalTotal,
158	            installments,
159	            installmentAmount,
160	            nextPurchaseCredit,
161	            gift
162	        );
163	    }
164	
165	    private BigDecimal calculateProductsSubtotal(List<OrderItemDTO> items) {
166	        BigDecimal subtotal = BigDecimal.ZERO;
167	        for (OrderItemDTO item : items) {
168	            Optional<Product> product = productRepository.findById(item.getSku());
169	            if (product.isPresent()) {
170	                BigDecimal itemPrice = PricingUtil.multiply(product.get().getPrice(), new BigDecimal(item.getQuantity()));
171	                subtotal = PricingUtil.add(subtotal, itemPrice);
172	            }
173	        }
174	        return subtotal;
175	    }
176	
177	    private BigDecimal calculateCouponDiscount(String coupon, BigDecimal subtotal, ShippingMethod shippingMethod, OrderRequestDTO request) {
178	        if (coupon == null || coupon.isEmpty()) {
179	            return BigDecimal.ZERO;
180	        }
181	
182	        BigDecimal discount = BigDecimal.ZERO;
183	
184	        if ("WELCOME10".equals(coupon)) {
185	            discount = PricingUtil.percentage(subtotal, new BigDecimal("10"));
186	        } else if ("MINUS50".equals(coupon)) {
187	            if (subtotal.compareTo(new BigDecimal("300")) >= 0) {
188	                discount = new BigDecimal("50.00");
189	            }
190	        } else if ("FREESHIPPING".equals(coupon)) {
191	            ShippingCostInfo shippingInfo = calculateShippingCost(request);
192	            discount = shippingInfo.cost;
193	        } else if ("BUY3PAY2".equals(coupon)) {
194	            discount = calculateBuy3Pay2Discount(request.getItems());
195	        }
196	
197	        BigDecimal maxDiscount = PricingUtil.percentage(subtotal, new BigDecimal("30"));
198	        if (discount.compareTo(maxDiscount) > 0) {
199	            discount = maxDiscount;
200	        }
201	
202	        return discount;
203	    }
204	
205	    private BigDecimal calculateBuy3Pay2Discount(List<OrderItemDTO> items) {
206	        BigDecimal discount = BigDecimal.ZERO;
207	
208	        for (OrderItemDTO item : items) {
209	            Optional<Product> product = productRepository.findById(item.getSku());
210	            if (product.isPresent()) {
211	                int quantity = item.getQuantity();
212	                int freeItems = quantity / 3;
213	                if (freeItems > 0) {
214	                    BigDecimal itemDiscount = PricingUtil.multiply(product.get().getPrice(), new BigDecimal(freeItems));
215	                    discount = PricingUtil.add(discount, itemDiscount);
216	                }
217	            }
218	        }
219	
220	        return discount;
221	    }
222	
223	    private class ShippingCostInfo {
224	        BigDecimal cost;
225	        Integer days;
226	
227	        ShippingCostInfo(BigDecimal cost, Integer days) {
228	            this.cost = cost;
229	            this.days = days;
230	        }
231	    }
232	
233	    private ShippingCostInfo calculateShippingCost(OrderRequestDTO request) {
234	        ShippingMethod method = request.getShippingMethod();
235	        Region region = request.getRegion();
236	        String zipCode = request.getZipCode();
237	        BigDecimal weight = calculateWeight(request.getItems());
238	
239	        if (method == ShippingMethod.STORE_PICKUP) {
240	            return new ShippingCostInfo(BigDecimal.ZERO, 1);
241	        }
242	
243	        if (method == ShippingMethod.COURIER) {
244	            if (weight.compareTo(new BigDecimal("5")) > 0) {
245	                throw new OrderException("SHIPPING_METHOD_UNAVAILABLE", "COURIER max weight is 5kg", HttpStatus.UNPROCESSABLE_ENTITY);
246	            }
247	            return new ShippingCostInfo(new BigDecimal("18.00"), 0);
248	        }
249	
250	        try {
251	            String service = method == ShippingMethod.ECONOMY ? "STD" : "EXP";
252	            TransLogClient.TransLogQuote quote = transLogClient.getQuote(zipCode, weight.multiply(new BigDecimal("1000")).intValue(), service);
253	
254	            BigDecimal cost = PricingUtil.round(quote.getPrice());
255	            int days = PricingUtil.ceilDays(quote.etaHours);
256	
257	            if (region == Region.NORTH && (method == ShippingMethod.ECONOMY || method == ShippingMethod.EXPRESS)) {
258	                days += 3;
259	            } else if (region == Region.NORTHEAST && (method == ShippingMethod.ECONOMY || method == ShippingMethod.EXPRESS)) {
260	                days += 2;
261	            }
262	
263	            return new ShippingCostInfo(cost, days);
264	        } catch (TransLogClient.TransLogException e) {
265	            if ("ZIP_NOT_SERVED".equals(e.getMessage())) {
266	                throw new OrderException("SHIPPING_METHOD_UNAVAILABLE", "TransLog does not serve this ZIP", HttpStatus.UNPROCESSABLE_ENTITY);
267	            }
268	            throw new OrderException("CARRIER_UNAVAILABLE", "TransLog is unavailable", HttpStatus.SERVICE_UNAVAILABLE);
269	        }
270	    }
271	
272	    private BigDecimal calculateWeight(List<OrderItemDTO> items) {
273	        BigDecimal totalWeight = BigDecimal.ZERO;
274	        for (OrderItemDTO item : items) {
275	            Optional<Product> product = productRepository.findById(item.getSku());
276	            if (product.isPresent()) {
277	                BigDecimal itemWeight = product.get().getWeightKg().multiply(new BigDecimal(item.getQuantity()));
278	                totalWeight = totalWeight.add(itemWeight);
279	            }
280	        }
281	        return totalWeight;
282	    }
283	
284	    private BigDecimal calculateInsurance(BigDecimal subtotal, Region region) {
285	        BigDecimal percentage;
286	        BigDecimal limit = null;
287	
288	        switch (region) {
289	            case SOUTHEAST, SOUTH -> percentage = new BigDecimal("1");
290	            case MIDWEST -> percentage = new BigDecimal("1.5");
291	            case NORTH -> {
292	                percentage = new BigDecimal("2.5");
293	                limit = new BigDecimal("30");
294	            }
295	            case NORTHEAST -> {
296	                percentage = new BigDecimal("2");
297	                limit = new BigDecimal("30");
298	            }
299	            default -> percentage = BigDecimal.ZERO;
300	        }
301	
302	        BigDecimal insurance = PricingUtil.percentage(subtotal, percentage);
303	
304	        if (limit != null && insurance.compareTo(limit) > 0) {
305	            insurance = limit;
306	        }
307	
308	        return insurance;
309	    }
310	
311	    private void validatePaymentMethodConstraints(OrderRequestDTO request, BigDecimal total) {
312	        if (request.getPaymentMethod() == PaymentMethod.BANK_SLIP) {
313	            if (total.compareTo(new BigDecimal("1000")) > 0) {
314	                throw new OrderException("PAYMENT_METHOD_UNAVAILABLE", "BANK_SLIP not available for orders over R$ 1.000,00", HttpStatus.UNPROCESSABLE_ENTITY);
315	            }
316	        }
317	    }
318	
319	    private class PaymentAdjustmentInfo {
320	        BigDecimal finalTotal;
321	        BigDecimal adjustment;
322	        Integer installments;
323	        BigDecimal installmentAmount;
324	
325	        PaymentAdjustmentInfo(BigDecimal finalTotal, BigDecimal adjustment, Integer installments, BigDecimal installmentAmount) {
326	            this.finalTotal = finalTotal;
327	            this.adjustment = adjustment;
328	            this.installments = installments;
329	            this.installmentAmount = installmentAmount;
330	        }
331	    }
332	
333	    private PaymentAdjustmentInfo calculatePaymentAdjustment(PaymentMethod method, BigDecimal subtotal, Integer installments, boolean hasCoupon) {
334	        int inst = installments != null ? installments : 1;
335	        BigDecimal adjustment = BigDecimal.ZERO;
336	        BigDecimal finalTotal = subtotal;
337	
338	        if (method == PaymentMethod.PIX && !hasCoupon) {
339	            BigDecimal discount = PricingUtil.percentage(subtotal, new BigDecimal("5"));
340	            adjustment = discount.negate();
341	            finalTotal = PricingUtil.subtract(subtotal, discount);
342	        } else if (method == PaymentMethod.BANK_SLIP) {
343	            adjustment = new BigDecimal("3.49");
344	            finalTotal = PricingUtil.add(subtotal, adjustment);
345	        } else if (method == PaymentMethod.CREDIT_CARD) {
346	            if (inst <= 3) {
347	                finalTotal = subtotal;
348	                adjustment = BigDecimal.ZERO;
349	            } else {
350	                BigDecimal monthlyRate = new BigDecimal("0.0199");
351	                BigDecimal multiplier = calculateInstallmentMultiplier(monthlyRate, inst);
352	                BigDecimal installmentValue = PricingUtil.multiply(subtotal, multiplier);
353	                finalTotal = PricingUtil.multiply(installmentValue, new BigDecimal(inst));
354	                adjustment = PricingUtil.subtract(finalTotal, subtotal);
355	            }
356	        }
357	
358	        BigDecimal installmentAmount = PricingUtil.divide(finalTotal, new BigDecimal(inst));
359	
360	        return new PaymentAdjustmentInfo(finalTotal, adjustment, inst, installmentAmount);
361	    }
362	
363	    private BigDecimal calculateInstallmentMultiplier(BigDecimal monthlyRate, Integer installments) {
364	        BigDecimal numerator = monthlyRate;
365	        BigDecimal denominator = BigDecimal.ONE;
366	        BigDecimal monthlyRatePlus1 = monthlyRate.add(BigDecimal.ONE);
367	
368	        BigDecimal power = monthlyRatePlus1.pow(installments);
369	        denominator = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(power, 10, java.math.RoundingMode.HALF_EVEN));
370	
371	        return numerator.divide(denominator, 10, java.math.RoundingMode.HALF_EVEN);
372	    }
373	
374	    private BigDecimal calculateNextPurchaseCredit(ClubTier tier, BigDecimal subtotal) {
375	        if (tier == ClubTier.SILVER) {
376	            return PricingUtil.percentage(subtotal, new BigDecimal("2"));
377	        } else if (tier == ClubTier.GOLD) {
378	            return PricingUtil.percentage(subtotal, new BigDecimal("5"));
379	        }
380	        return BigDecimal.ZERO;
381	    }
382	
383	    private Boolean shouldGiveGift(ClubTier tier, BigDecimal subtotal) {
384	        if (tier == ClubTier.GOLD && subtotal.compareTo(new BigDecimal("500")) > 0) {
385	            return true;
386	        }
387	        return false;
388	    }
389	}
